WITH changed AS ( INSERT INTO environment_work ( uuid, external_id, organization_uuid, workspace_uuid, environment_uuid, environment_external_id, session_uuid, metadata, secret, state, created_at, updated_at ) SELECT #{params.UUID}, #{params.ExternalID}, #{params.OrganizationUUID}, #{params.WorkspaceUUID}, #{params.EnvironmentUUID}, #{params.EnvironmentExternalID}, #{params.SessionUUID}, CAST(#{params.Metadata,sensitive=true} AS jsonb), #{params.Secret,sensitive=true}, #{params.State}, #{params.CreatedAt}, #{params.CreatedAt} FROM sessions source_session WHERE source_session.organization_uuid = #{params.OrganizationUUID} AND source_session.workspace_uuid = #{params.WorkspaceUUID} AND source_session.environment_uuid = #{params.EnvironmentUUID} AND source_session.uuid = #{params.SessionUUID} AND source_session.deleted_at IS NULL RETURNING
) SELECT
FROM changed work

