WITH changed AS ( UPDATE environment_work SET claimed_by_worker_id = #{workerID}, claim_expires_at = #{claimExpiresAt}, updated_at = NOW() WHERE uuid = ( SELECT uuid FROM environment_work WHERE workspace_uuid = #{workspaceUUID} AND environment_external_id = #{environmentExternalID} AND deleted_at IS NULL AND state = 'queued' AND (claim_expires_at IS NULL OR claim_expires_at <= NOW()) ORDER BY created_at ASC, uuid ASC LIMIT 1 FOR UPDATE SKIP LOCKED ) RETURNING
) SELECT
FROM changed work

WITH changed AS ( UPDATE environment_work SET claimed_by_worker_id = #{workerID}, claim_expires_at = #{claimExpiresAt}, updated_at = NOW() WHERE uuid = ( SELECT uuid FROM environment_work WHERE deleted_at IS NULL AND state = 'queued' AND (claim_expires_at IS NULL OR claim_expires_at <= NOW()) ORDER BY created_at ASC, uuid ASC LIMIT 1 FOR UPDATE SKIP LOCKED ) RETURNING
) SELECT
FROM changed work

