WITH changed AS ( UPDATE environment_work SET state = CASE WHEN state = 'queued' THEN 'starting' ELSE state END, acknowledged_at = COALESCE(acknowledged_at, NOW()), started_at = COALESCE(started_at, NOW()), claim_expires_at = NULL, updated_at = NOW() WHERE workspace_uuid = #{workspaceUUID} AND environment_external_id = #{environmentExternalID} AND external_id = #{workExternalID} AND deleted_at IS NULL AND state IN ('queued', 'starting', 'active') RETURNING
) SELECT
FROM changed work

